 </div>\n</form>\n</div>\n<script type=\"text/javascript\" src=\"//s3.amazonaws.com/downloads.mailchimp.com/js/mc-validate.js\"></script><script type=\"text/javascript\">(function($) {window.fnames = new Array(); window.ftypes = new Array();fnames[1]=\'FNAME\';ftypes[1]=\'text\';fnames[2]=\'LNAME\';ftypes[2]=\'text\';fnames[0]=\'EMAIL\';ftypes[0]=\'email\';fnames[16]=\'PROGSTAT\';ftypes[16]=\'dropdown\';fnames[8]=\'DONOTCONTA\';ftypes[8]=\'text\';fnames[22]=\'LASTYRGIFT\';ftypes[22]=\'number\';fnames[13]=\'THISYRGIFT\';ftypes[13]=\'number\';fnames[21]=\'LASTSFSYNC\';ftypes[21]=\'date\';fnames[20]=\'MMERGE20\';ftypes[20]=\'number\';fnames[19]=\'MMERGE19\';ftypes[19]=\'text\';fnames[18]=\'PRIMARYCON\';ftypes[18]=\'text\';fnames[17]=\'PREFERREDN\';ftypes[17]=\'text\';fnames[12]=\'STATE\';ftypes[12]=\'text\';fnames[15]=\'GENDER\';ftypes[15]=\'dropdown\';fnames[11]=\'SFCONTYPE\';ftypes[11]=\'text\';fnames[10]=\'TOTALGIFTS\';ftypes[10]=\'number\';fnames[7]=\'SOLICITATI\';ftypes[7]=\'number\';fnames[6]=\'MENTOR\';ftypes[6]=\'text\';fnames[4]=\'ALUMNUS\';ftypes[4]=\'text\';fnames[9]=\'SFCONTACTI\';ftypes[9]=\'text\';fnames[3]=\'LASTDONDAT\';ftypes[3]=\'date\';fnames[5]=\'ACCTOWN\';ftypes[5]=\'text\';}(jQuery));var $mcj = jQuery.noConflict(true);\n    // SMS Phone Multi-Country Functionality\n    if(!window.MC) {\n      window.MC = {};\n    }\n    window.MC.smsPhoneData = {\n      defaultCountryCode: \'US\',\n      programs: [],\n      smsProgramDataCountryNames: []\n    };\n\n    function getCountryUnicodeFlag(countryCode) {\n       return countryCode.toUpperCase().replace(/./g, (char) => String.fromCodePoint(char.charCodeAt(0) + 127397))\n    };\n\n    // HTML sanitization function to prevent XSS\n    function sanitizeHtml(str) {\n      if (typeof str !== \'string\') return \'\';\n      return str\n        .replace(/&/g, \'&amp;\')\n        .replace(/</g, \'&lt;\')\n        .replace(/>/g, \'&gt;\')\n        .replace(/\"/g, \'&quot;\')\n        .replace(/\'/g, \'&#x27;\')\n        .replace(/\\//g, \'&#x2F;\');\n    }\n\n    // URL sanitization function to prevent javascript: and data: URLs\n    function sanitizeUrl(url) {\n      if (typeof url !== \'string\') return \'\';\n      const trimmedUrl = url.trim().toLowerCase();\n      if (trimmedUrl.startsWith(\'javascript:\') || trimmedUrl.startsWith(\'data:\') || trimmedUrl.startsWith(\'vbscript:\')) {\n        return \'#\';\n      }\n      return url;\n    }\n\n    const getBrowserLanguage = () => {\n      if (!window?.navigator?.language?.split(\'-\')[1]) {\n        return window?.navigator?.language?.toUpperCase();\n      }\n      return window?.navigator?.language?.split(\'-\')[1];\n    };\n\n    function getDefaultCountryProgram(defaultCountryCode, smsProgramData) {\n      if (!smsProgramData || smsProgramData.length === 0) {\n        return null;\n      }\n\n      const browserLanguage = getBrowserLanguage();\n\n      if (browserLanguage) {\n        const foundProgram = smsProgramData.find(\n          (program) => program?.countryCode === browserLanguage,\n        );\n        if (foundProgram) {\n          return foundProgram;\n        }\n      }\n\n      if (defaultCountryCode) {\n        const foundProgram = smsProgramData.find(\n          (program) => program?.countryCode === defaultCountryCode,\n        );\n        if (foundProgram) {\n          return foundProgram;\n        }\n      }\n\n      return smsProgramData[0];\n    }\n\n    function updateSmsLegalText(countryCode, fieldName) {\n      if (!countryCode || !fieldName) {\n        return;\n      }\n      \n      const programs = window?.MC?.smsPhoneData?.programs;\n      if (!programs || !Array.isArray(programs)) {\n        return;\n      }\n      \n      const program = programs.find(program => program?.countryCode === countryCode);\n      if (!program || !program.requiredTemplate) {\n        return;\n      }\n      \n      const legalTextElement = document.querySelector(\'#legal-text-\' + fieldName);\n      if (!legalTextElement) {\n        return;\n      }\n      \n      // Remove HTML tags and clean up the text\n      const divRegex = new RegExp(\'</?[div][^>]*>\', \'gi\');\n      const fullAnchorRegex = new RegExp(\'<a.*?</a>\', \'g\');\n      const anchorRegex = new RegExp(\'<a href=\"(.*?)\" target=\"(.*?)\">(.*?)</a>\');\n      \n      const template = program.requiredTemplate.replace(divRegex, \'\');\n      \n      \n\n      legalTextElement.textContent = \'\';\n      const parts = template.split(/(<a href=\".*?\" target=\".*?\">.*?<\\/a>)/g);\n      parts.forEach(function(part) {\n        if (!part) {\n          return;\n        }\n        const anchorMatch = part.match(/<a href=\"(.*?)\" target=\"(.*?)\">(.*?)<\\/a>/);\n        if (anchorMatch) {\n          const linkElement = document.createElement(\'a\');\n          linkElement.href = sanitizeUrl(anchorMatch[1]);\n          linkElement.target = sanitizeHtml(anchorMatch[2]);\n          linkElement.textContent = sanitizeHtml(anchorMatch[3]);\n          legalTextElement.appendChild(linkElement);\n        } else {\n          legalTextElement.appendChild(document.createTextNode(part));\n        }\n      });\n          \n    }\n\n    function generateDropdownOptions(smsProgramData) {\n      if (!smsProgramData || smsProgramData.length === 0) {\n        return \'\';\n      }\n      \n      return smsProgramData.map(program => {\n        const flag = getCountryUnicodeFlag(program.countryCode);\n        const countryName = getCountryName(program.countryCode);\n        const callingCode = program.countryCallingCode || \'\';\n        // Sanitize all values to prevent XSS\n        const sanitizedCountryCode = sanitizeHtml(program.countryCode || \'\');\n        const sanitizedCountryName = sanitizeHtml(countryName || \'\');\n        const sanitizedCallingCode = sanitizeHtml(callingCode || \'\');\n        return \'<option value=\"\' + sanitizedCountryCode + \'\">\' + sanitizedCountryName + \' \' + sanitizedCallingCode + \'</option>\';\n      }).join(\'\');\n    }\n\n    function getCountryName(countryCode) {\n      if (window.MC?.smsPhoneData?.smsProgramDataCountryNames && Array.isArray(window.MC.smsPhoneData.smsProgramDataCountryNames)) {\n        for (let i = 0; i < window.MC.smsPhoneData.smsProgramDataCountryNames.length; i++) {\n          if (window.MC.smsPhoneData.smsProgramDataCountryNames[i].code === countryCode) {\n            return window.MC.smsPhoneData.smsProgramDataCountryNames[i].name;\n          }\n        }\n      }\n      return countryCode;\n    }\n\n    function getDefaultPlaceholder(countryCode) {\n      if (!countryCode || typeof countryCode !== \'string\') {\n        return \'+1 000 000 0000\'; // Default US placeholder\n      }\n      \n            var mockPlaceholders = [\n        {\n          countryCode: \'US\',\n          placeholder: \'+1 000 000 0000\',\n          helpText: \'Include the US country code +1 before the phone number\',\n        },\n        {\n          countryCode: \'GB\',\n          placeholder: \'+44 0000 000000\',\n          helpText: \'Include the GB country code +44 before the phone number\',\n        },\n        {\n          countryCode: \'CA\',\n          placeholder: \'+1 000 000 0000\',\n          helpText: \'Include the CA country code +1 before the phone number\',\n        },\n        {\n          countryCode: \'AU\',\n          placeholder: \'+61 000 000 000\',\n          helpText: \'Include the AU country code +61 before the phone number\',\n        },\n        {\n          countryCode: \'DE\',\n          placeholder: \'+49 000 0000000\',\n          helpText: \'Fügen Sie vor der Telefonnummer die DE-Ländervorwahl +49 ein\',\n        },\n        {\n          countryCode: \'FR\',\n          placeholder: \'+33 0 00 00 00 00\',\n          helpText: \'Incluez le code pays FR +33 avant le numéro de téléphone\',\n        },\n        {\n          countryCode: \'ES\',\n          placeholder: \'+34 000 000 000\',\n          helpText: \'Incluya el cód